&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_10&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Voici les options accessibles aux hommes-rats, d’autres races adapt&#233;es peuvent s’en servir si le MJ donne son accord.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_0&quot; href=&quot;#Dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table CLASS=&quot;tablo centre autoalt toutgauche&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH= &quot;6%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;44%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cachette-Commune.html&quot; title=&quot;Cachette commune&quot;&gt;Cachette commune&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1, 1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;, trait racial &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html#Traits_raciaux_standards_7&quot; title=&quot;Les hommes-rats&quot;&gt;regroupement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;R&#233;cup&#232;re rapidement des objets port&#233;s par les alli&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collectionneur.html&quot; title=&quot;Collectionneur&quot;&gt;Collectionneur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Poss&#232;de toujours des objets aux hasard sur sa personne au besoin&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dents-Ac&#233;r&#233;es.html&quot; title=&quot;Dents ac&#233;r&#233;es&quot;&gt;Dents ac&#233;r&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain d&#39;une attaque de morsure&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Rogneur.html&quot; title=&quot;Rogneur&quot;&gt;Rogneur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dents-Ac&#233;r&#233;es.html&quot; title=&quot;Dents ac&#233;r&#233;es&quot;&gt;Dents ac&#233;r&#233;es&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;homme-rat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Ignore la solidit&#233; des objets avec une morsure puissante&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Griffe-Tranchante.html&quot; title=&quot;Griffe-tranchante&quot;&gt;Griffe-tranchante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage obtient deux attaques de griffes&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rat-Des-Tunnels.html&quot; title=&quot;Rat des tunnels&quot;&gt;Rat des tunnels&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;, trait racial regroupement&lt;/td&gt;&lt;td&gt;Le personnage est plus difficile &#224; &#233;craser&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Dents-De-Fouisseur.html&quot; title=&quot;Dents de fouisseur&quot;&gt;Dents de fouisseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Griffe-Tranchante.html&quot; title=&quot;Griffe-tranchante&quot;&gt;griffe-tranchante&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rat-Des-Tunnels.html&quot; title=&quot;Rat des tunnels&quot;&gt;rat des tunnels&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage dispose d&#39;une vitesse de creusement&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
